-- =============================================================================
-- verify/02_generator.sql — Requirement 2: data generated by a stored procedure,
-- >= 100 000 rows over 3-4 months. Primary only. Read-only.
-- =============================================================================
\set ON_ERROR_STOP 1
\pset footer off
BEGIN;

CREATE TEMP TABLE vr (n serial, check_name text, passed boolean, details text) ON COMMIT DROP;

-- 1. Generator is a stored procedure
INSERT INTO vr (check_name, passed, details)
SELECT 'ops.generate_operations is a stored PROCEDURE', count(*) = 1,
       string_agg(oid::regprocedure::text, '; ')
FROM pg_proc WHERE oid = 'ops.generate_operations'::regproc AND prokind = 'p';

-- 2. Volume
INSERT INTO vr (check_name, passed, details)
SELECT 'At least 100 000 rows', count(*) >= 100000, format('%s rows', count(*))
FROM ops.operations;

-- 3. Period: 3-4 months of data, every calendar day has data
INSERT INTO vr (check_name, passed, details)
SELECT 'Data spans at least 3 months (and the seed at most 4)',
       max(op_date) - min(op_date) >= interval '3 months'
         AND min(op_date) >= (SELECT min(registered_at) FROM ops.operation_guid_registry) - interval '4 months' - interval '1 minute',
       format('%s .. %s (%s)', min(op_date)::timestamp(0), max(op_date)::timestamp(0), date_trunc('second', max(op_date) - min(op_date)))
FROM ops.operations;

INSERT INTO vr (check_name, passed, details)
SELECT 'No day without data inside the period', count(*) = 0, format('%s empty day(s)', count(*))
FROM generate_series((SELECT date_trunc('day', min(op_date)) FROM ops.operations),
                     (SELECT date_trunc('day', max(op_date)) FROM ops.operations), interval '1 day') d
WHERE NOT EXISTS (SELECT 1 FROM ops.operations o WHERE o.op_date >= d AND o.op_date < d + interval '1 day');

-- 4. Partitions: data spread over monthly partitions, DEFAULT empty
INSERT INTO vr (check_name, passed, details)
SELECT 'Rows spread over monthly partitions, DEFAULT empty',
       bool_and(part <> 'ops.operations_default'::regclass) AND count(*) >= 4,
       string_agg(format('%s=%s', part, cnt), ', ' ORDER BY part::text)
FROM (SELECT tableoid::regclass AS part, count(*) AS cnt FROM ops.operations GROUP BY 1) p;

-- 5. Status distribution (D-11): nothing pending older than 24 h, the last 24 h mostly pending
INSERT INTO vr (check_name, passed, details)
SELECT 'No pending (status 0) operation older than 24 h',
       count(*) FILTER (WHERE status = 0 AND op_date < now() - interval '24 hours') = 0,
       format('status 1: %s, status 0: %s (of which older than 24 h: %s)',
              count(*) FILTER (WHERE status = 1), count(*) FILTER (WHERE status = 0),
              count(*) FILTER (WHERE status = 0 AND op_date < now() - interval '24 hours'))
FROM ops.operations;

-- 6. Message contract & domain consistency (D-13)
INSERT INTO vr (check_name, passed, details)
SELECT 'Each account number belongs to exactly one client', count(*) = 0, format('%s shared account(s)', count(*))
FROM (SELECT message->>'account_number' FROM ops.operations GROUP BY 1
      HAVING count(DISTINCT message->>'client_id') > 1) s;

INSERT INTO vr (check_name, passed, details)
SELECT 'All account numbers are valid IBANs (mod-97 = 1)', count(*) = 0, format('%s invalid', count(*))
FROM (SELECT DISTINCT message->>'account_number' AS acc FROM ops.operations) a
WHERE (substr(acc, 5) || '3010' || substr(acc, 3, 2))::numeric % 97 <> 1;

INSERT INTO vr (check_name, passed, details)
SELECT 'Client pool and operation types look realistic',
       count(DISTINCT message->>'client_id') BETWEEN 900 AND 1000
         AND count(*) FILTER (WHERE message->>'operation_type' = 'online') > count(*) FILTER (WHERE message->>'operation_type' = 'offline')
         AND count(*) FILTER (WHERE message->>'operation_type' = 'offline') > 0,
       format('%s clients, %s accounts, online %s / offline %s',
              count(DISTINCT message->>'client_id'), count(DISTINCT message->>'account_number'),
              count(*) FILTER (WHERE message->>'operation_type' = 'online'),
              count(*) FILTER (WHERE message->>'operation_type' = 'offline'))
FROM ops.operations;

-- 7. Amounts
INSERT INTO vr (check_name, passed, details)
SELECT 'Amounts are positive, between 1.00 and 50 000.00',
       min(amount) >= 1 AND max(amount) <= 50000,
       format('min %s, median %s, max %s, total %s', min(amount),
              percentile_cont(0.5) WITHIN GROUP (ORDER BY amount), max(amount), sum(amount))
FROM ops.operations;

-- 8. Ids grow with op_date (chronological batches)
INSERT INTO vr (check_name, passed, details)
SELECT 'Ids grow with op_date (no id inversions)', count(*) = 0, format('%s inversion(s)', count(*))
FROM (SELECT id < lag(id) OVER (ORDER BY op_date, id) AS inv FROM ops.operations) s
WHERE inv;

-- 9. Every row went through the uniqueness path
INSERT INTO vr (check_name, passed, details)
SELECT 'Registry has one row per operation', r.cnt = o.cnt, format('registry %s, operations %s', r.cnt, o.cnt)
FROM (SELECT count(*) cnt FROM ops.operation_guid_registry) r, (SELECT count(*) cnt FROM ops.operations) o;

SELECT n AS "#", CASE WHEN passed THEN 'PASS' ELSE 'FAIL' END AS result, check_name, details FROM vr ORDER BY n;
ROLLBACK;
